module legacy_result_boundaries;
pub struct Box<T> { value:T; }
fn identity<T>(value:T)->T { return value; }
fn read(value:result<i64>)->result<str> {
  match value { ok(n)=>{return ok("value="+str(n));} err(code,message)=>{return err(code,message);} }
}
fn main()->unit!{io} {
  let propagate:Box<str> = Box(identity("Я\u0000🦊"));
  print(propagate.value);
  print(read(ok(42)));
  print(read(err<i64>("OLD", "same error")));
}
test fn values()->unit {
  assert(read(ok(42))==ok("value=42"));
  assert(read(err<i64>("OLD", "same error"))==err<str>("OLD", "same error"));
}
